    val all = listOf(
        ShortLesson("MATEMATICAS:0:0", MateriaId.MATEMATICAS, 0, "Valor posicional", "El valor de una cifra depende de su posición. De derecha a izquierda aparecen unidades, decenas y centenas.", "En 352, el 3 representa 300, el 5 representa 50 y el 2 representa 2.", "El valor de una cifra depende de su posición.", listOf("Decena" to "Grupo de diez unidades", "Centena" to "Grupo de cien unidades"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Grupo de diez unidades.", listOf("Decena", "Centena"), 0, "Decena: Grupo de diez unidades."), ShortQuestion("¿Qué concepto corresponde a esta definición? Grupo de cien unidades.", listOf("Decena", "Centena"), 1, "Centena: Grupo de cien unidades.")), null, "es-MX", null),
        ShortLesson("MATEMATICAS:0:1", MateriaId.MATEMATICAS, 0, "Fracciones", "Una fracción expresa partes iguales de una unidad. El denominador indica cuántas partes iguales hay y el numerador cuántas se consideran.", "Si divides una figura en cuatro partes iguales y marcas tres, has marcado 3/4.", "Una fracción expresa partes iguales de una unidad.", listOf("Numerador" to "Número de partes consideradas", "Denominador" to "Número de partes iguales de la unidad"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Número de partes consideradas.", listOf("Numerador", "Denominador"), 0, "Numerador: Número de partes consideradas."), ShortQuestion("¿Qué concepto corresponde a esta definición? Número de partes iguales de la unidad.", listOf("Numerador", "Denominador"), 1, "Denominador: Número de partes iguales de la unidad.")), null, "es-MX", null),
        ShortLesson("MATEMATICAS:1:0", MateriaId.MATEMATICAS, 1, "Ecuaciones", "Una ecuación afirma que dos expresiones tienen el mismo valor. Sumar o restar la misma cantidad en ambos lados conserva la igualdad.", "Para resolver x + 3 = 8, resta 3 en ambos lados: x = 5.", "Una ecuación afirma que dos expresiones tienen el mismo valor.", listOf("Incógnita" to "Valor que se busca en una ecuación", "Solución" to "Valor que hace verdadera la igualdad"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Valor que se busca en una ecuación.", listOf("Incógnita", "Solución"), 0, "Incógnita: Valor que se busca en una ecuación."), ShortQuestion("¿Qué concepto corresponde a esta definición? Valor que hace verdadera la igualdad.", listOf("Incógnita", "Solución"), 1, "Solución: Valor que hace verdadera la igualdad.")), null, "es-MX", null),
        ShortLesson("MATEMATICAS:1:1", MateriaId.MATEMATICAS, 1, "Área y perímetro", "El perímetro mide el contorno de una figura. El área mide la superficie que ocupa. En un rectángulo, el área es base por altura.", "Un rectángulo de 4 cm por 3 cm tiene área de 12 cm² y perímetro de 14 cm.", "El perímetro mide el contorno de una figura.", listOf("Área" to "Medida de una superficie", "Perímetro" to "Longitud del contorno"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Medida de una superficie.", listOf("Área", "Perímetro"), 0, "Área: Medida de una superficie."), ShortQuestion("¿Qué concepto corresponde a esta definición? Longitud del contorno.", listOf("Área", "Perímetro"), 1, "Perímetro: Longitud del contorno.")), null, "es-MX", "rectangle"),
        ShortLesson("ESPANOL:0:0", MateriaId.ESPANOL, 0, "Sustantivos y verbos", "Un sustantivo nombra entidades, ideas o lugares. Un verbo expresa acciones, procesos o estados y puede conjugarse.", "En «La estudiante observa», estudiante es sustantivo y observa es verbo.", "Un sustantivo nombra entidades, ideas o lugares.", listOf("Sustantivo" to "Palabra que nombra entidades o ideas", "Verbo" to "Palabra que expresa acciones, procesos o estados"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Palabra que nombra entidades o ideas.", listOf("Sustantivo", "Verbo"), 0, "Sustantivo: Palabra que nombra entidades o ideas."), ShortQuestion("¿Qué concepto corresponde a esta definición? Palabra que expresa acciones, procesos o estados.", listOf("Sustantivo", "Verbo"), 1, "Verbo: Palabra que expresa acciones, procesos o estados.")), null, "es-MX", null),
        ShortLesson("ESPANOL:0:1", MateriaId.ESPANOL, 0, "Sujeto y predicado", "El sujeto concuerda con el verbo en número y persona. El predicado expresa lo que se dice del sujeto.", "En «Los planetas orbitan el Sol», Los planetas es el sujeto y orbitan el Sol es el predicado.", "El sujeto concuerda con el verbo en número y persona.", listOf("Sujeto" to "Parte que concuerda con el verbo", "Predicado" to "Parte que expresa lo que se dice del sujeto"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Parte que concuerda con el verbo.", listOf("Sujeto", "Predicado"), 0, "Sujeto: Parte que concuerda con el verbo."), ShortQuestion("¿Qué concepto corresponde a esta definición? Parte que expresa lo que se dice del sujeto.", listOf("Sujeto", "Predicado"), 1, "Predicado: Parte que expresa lo que se dice del sujeto.")), null, "es-MX", null),
        ShortLesson("ESPANOL:1:0", MateriaId.ESPANOL, 1, "Acentuación", "Las palabras agudas tienen la sílaba tónica al final y llevan tilde si terminan en vocal, n o s. Las esdrújulas tienen la tónica en la antepenúltima sílaba y siempre llevan tilde.", "Café es aguda y lleva tilde porque termina en vocal. Música es esdrújula.", "Las palabras agudas tienen la sílaba tónica al final y llevan tilde si terminan en vocal, n o s.", listOf("Aguda" to "Palabra con sílaba tónica final", "Esdrújula" to "Palabra con sílaba tónica antepenúltima"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Palabra con sílaba tónica final.", listOf("Aguda", "Esdrújula"), 0, "Aguda: Palabra con sílaba tónica final."), ShortQuestion("¿Qué concepto corresponde a esta definición? Palabra con sílaba tónica antepenúltima.", listOf("Aguda", "Esdrújula"), 1, "Esdrújula: Palabra con sílaba tónica antepenúltima.")), null, "es-MX", null),
        ShortLesson("ESPANOL:1:1", MateriaId.ESPANOL, 1, "Conectores", "Los conectores expresan relaciones entre ideas. Algunos indican causa y otros presentan una oposición.", "«No salimos porque llovía» expresa causa. «Llovía, sin embargo salimos» expresa contraste.", "Los conectores expresan relaciones entre ideas.", listOf("Porque" to "Conector que introduce una causa", "Sin embargo" to "Conector que introduce un contraste"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Conector que introduce una causa.", listOf("Porque", "Sin embargo"), 0, "Porque: Conector que introduce una causa."), ShortQuestion("¿Qué concepto corresponde a esta definición? Conector que introduce un contraste.", listOf("Porque", "Sin embargo"), 1, "Sin embargo: Conector que introduce un contraste.")), null, "es-MX", null),
