        ShortLesson("FISICA:0:0", MateriaId.FISICA, 0, "Magnitudes y unidades", "Una magnitud física es una propiedad medible. Su valor se expresa con un número y una unidad.", "Una mesa puede tener una longitud de 2 metros; el 2 es el valor numérico y metro es la unidad.", "Una magnitud física es una propiedad medible.", listOf("Metro" to "Unidad de longitud", "Segundo" to "Unidad de tiempo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Unidad de longitud.", listOf("Metro", "Segundo"), 0, "Metro: Unidad de longitud."), ShortQuestion("¿Qué concepto corresponde a esta definición? Unidad de tiempo.", listOf("Metro", "Segundo"), 1, "Segundo: Unidad de tiempo.")), null, "es-MX", null),
