        ShortLesson("FISICA:1:1", MateriaId.FISICA, 1, "Energía", "La energía cinética está asociada al movimiento. La energía potencial depende de la configuración de un sistema.", "Una pelota que se mueve tiene energía cinética. Al elevarla aumenta su energía potencial gravitatoria respecto al suelo.", "La energía cinética está asociada al movimiento.", listOf("Cinética" to "Energía asociada al movimiento", "Potencial" to "Energía asociada a la configuración"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Energía asociada al movimiento.", listOf("Cinética", "Potencial"), 0, "Cinética: Energía asociada al movimiento."), ShortQuestion("¿Qué concepto corresponde a esta definición? Energía asociada a la configuración.", listOf("Cinética", "Potencial"), 1, "Potencial: Energía asociada a la configuración.")), null, "es-MX", null),
        ShortLesson("QUIMICA:0:0", MateriaId.QUIMICA, 0, "El átomo", "Un átomo posee un núcleo con protones y, habitualmente, neutrones. Los electrones se distribuyen alrededor del núcleo.", "El átomo neutro de hidrógeno más común tiene un protón y un electrón, sin neutrones.", "Un átomo posee un núcleo con protones y, habitualmente, neutrones.", listOf("Protón" to "Partícula con carga positiva", "Electrón" to "Partícula con carga negativa"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Partícula con carga positiva.", listOf("Protón", "Electrón"), 0, "Protón: Partícula con carga positiva."), ShortQuestion("¿Qué concepto corresponde a esta definición? Partícula con carga negativa.", listOf("Protón", "Electrón"), 1, "Electrón: Partícula con carga negativa.")), null, "es-MX", null),
        ShortLesson("QUIMICA:0:1", MateriaId.QUIMICA, 0, "Elementos y compuestos", "Un elemento se define por el número de protones de sus átomos. Un compuesto contiene elementos unidos químicamente en proporciones definidas.", "El oxígeno es un elemento. El agua es un compuesto cuya fórmula es H₂O.", "Un elemento se define por el número de protones de sus átomos.", listOf("Elemento" to "Sustancia formada por un tipo de átomo", "Compuesto" to "Sustancia con elementos unidos químicamente"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Sustancia formada por un tipo de átomo.", listOf("Elemento", "Compuesto"), 0, "Elemento: Sustancia formada por un tipo de átomo."), ShortQuestion("¿Qué concepto corresponde a esta definición? Sustancia con elementos unidos químicamente.", listOf("Elemento", "Compuesto"), 1, "Compuesto: Sustancia con elementos unidos químicamente.")), null, "es-MX", null),
        ShortLesson("QUIMICA:1:0", MateriaId.QUIMICA, 1, "Cambios de la materia", "Un cambio físico conserva la identidad química de las sustancias. Un cambio químico produce sustancias diferentes.", "Derretir hielo es un cambio físico. La oxidación del hierro es un cambio químico.", "Un cambio físico conserva la identidad química de las sustancias.", listOf("Cambio físico" to "Transformación sin nuevas sustancias", "Cambio químico" to "Transformación que produce nuevas sustancias"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Transformación sin nuevas sustancias.", listOf("Cambio físico", "Cambio químico"), 0, "Cambio físico: Transformación sin nuevas sustancias."), ShortQuestion("¿Qué concepto corresponde a esta definición? Transformación que produce nuevas sustancias.", listOf("Cambio físico", "Cambio químico"), 1, "Cambio químico: Transformación que produce nuevas sustancias.")), null, "es-MX", null),
        ShortLesson("QUIMICA:1:1", MateriaId.QUIMICA, 1, "Mezclas", "Una mezcla homogénea presenta composición uniforme a la escala observada. Una heterogénea presenta regiones distinguibles.", "La sal completamente disuelta en agua forma una mezcla homogénea. Agua y aceite separados forman una heterogénea.", "Una mezcla homogénea presenta composición uniforme a la escala observada.", listOf("Homogénea" to "Mezcla de composición uniforme", "Heterogénea" to "Mezcla con regiones distinguibles"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Mezcla de composición uniforme.", listOf("Homogénea", "Heterogénea"), 0, "Homogénea: Mezcla de composición uniforme."), ShortQuestion("¿Qué concepto corresponde a esta definición? Mezcla con regiones distinguibles.", listOf("Homogénea", "Heterogénea"), 1, "Heterogénea: Mezcla con regiones distinguibles.")), null, "es-MX", null),
        ShortLesson("BIOLOGIA:0:0", MateriaId.BIOLOGIA, 0, "La célula", "La célula es la unidad estructural y funcional básica de los seres vivos. La membrana delimita su interior y regula intercambios.", "Una bacteria es un organismo unicelular. Un árbol contiene muchas células especializadas.", "La célula es la unidad estructural y funcional básica de los seres vivos.", listOf("Membrana celular" to "Límite que regula intercambios", "Citoplasma" to "Medio interno donde ocurren procesos celulares"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Límite que regula intercambios.", listOf("Membrana celular", "Citoplasma"), 0, "Membrana celular: Límite que regula intercambios."), ShortQuestion("¿Qué concepto corresponde a esta definición? Medio interno donde ocurren procesos celulares.", listOf("Membrana celular", "Citoplasma"), 1, "Citoplasma: Medio interno donde ocurren procesos celulares.")), null, "es-MX", null),
        ShortLesson("BIOLOGIA:0:1", MateriaId.BIOLOGIA, 0, "Tipos celulares", "Las células eucariotas poseen un núcleo delimitado por membrana. Las procariotas carecen de ese núcleo.", "Las células animales y vegetales son eucariotas. Las bacterias son procariotas.", "Las células eucariotas poseen un núcleo delimitado por membrana.", listOf("Eucariota" to "Célula con núcleo delimitado", "Procariota" to "Célula sin núcleo delimitado"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Célula con núcleo delimitado.", listOf("Eucariota", "Procariota"), 0, "Eucariota: Célula con núcleo delimitado."), ShortQuestion("¿Qué concepto corresponde a esta definición? Célula sin núcleo delimitado.", listOf("Eucariota", "Procariota"), 1, "Procariota: Célula sin núcleo delimitado.")), null, "es-MX", null),
        ShortLesson("BIOLOGIA:1:0", MateriaId.BIOLOGIA, 1, "ADN y genes", "El ADN almacena información hereditaria. Un gen es una región de ADN que contribuye a producir un producto funcional.", "Una variante de un gen puede cambiar la secuencia de una proteína y modificar su funcionamiento.", "El ADN almacena información hereditaria.", listOf("ADN" to "Molécula que almacena información hereditaria", "Gen" to "Región de ADN con función biológica"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Molécula que almacena información hereditaria.", listOf("ADN", "Gen"), 0, "ADN: Molécula que almacena información hereditaria."), ShortQuestion("¿Qué concepto corresponde a esta definición? Región de ADN con función biológica.", listOf("ADN", "Gen"), 1, "Gen: Región de ADN con función biológica.")), null, "es-MX", null),
        ShortLesson("BIOLOGIA:1:1", MateriaId.BIOLOGIA, 1, "Ecosistemas", "Un ecosistema incluye organismos y su ambiente físico. Los productores generan materia orgánica y los consumidores la obtienen de otros organismos.", "En una pradera, el pasto es productor y el conejo que lo come es consumidor.", "Un ecosistema incluye organismos y su ambiente físico.", listOf("Productor" to "Organismo que genera materia orgánica a partir de fuentes inorgánicas", "Consumidor" to "Organismo que se alimenta de otros organismos"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Organismo que genera materia orgánica a partir de fuentes inorgánicas.", listOf("Productor", "Consumidor"), 0, "Productor: Organismo que genera materia orgánica a partir de fuentes inorgánicas."), ShortQuestion("¿Qué concepto corresponde a esta definición? Organismo que se alimenta de otros organismos.", listOf("Productor", "Consumidor"), 1, "Consumidor: Organismo que se alimenta de otros organismos.")), null, "es-MX", null),
        ShortLesson("HISTORIA:0:0", MateriaId.HISTORIA, 0, "Fuentes históricas", "Las fuentes permiten investigar el pasado. Una fuente primaria procede del periodo o proceso estudiado; una secundaria lo analiza posteriormente.", "Una carta escrita durante una guerra es fuente primaria. Un estudio posterior sobre esa guerra es secundario.", "Las fuentes permiten investigar el pasado.", listOf("Fuente primaria" to "Testimonio del periodo estudiado", "Fuente secundaria" to "Análisis posterior de fuentes"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Testimonio del periodo estudiado.", listOf("Fuente primaria", "Fuente secundaria"), 0, "Fuente primaria: Testimonio del periodo estudiado."), ShortQuestion("¿Qué concepto corresponde a esta definición? Análisis posterior de fuentes.", listOf("Fuente primaria", "Fuente secundaria"), 1, "Fuente secundaria: Análisis posterior de fuentes.")), null, "es-MX", null),
        ShortLesson("HISTORIA:0:1", MateriaId.HISTORIA, 0, "Cronología", "La cronología sitúa acontecimientos en el tiempo. Una secuencia temporal no demuestra por sí sola una relación causal.", "Que una reforma ocurra antes de una protesta no basta para afirmar que la causó: hay que consultar evidencias.", "La cronología sitúa acontecimientos en el tiempo.", listOf("Cronología" to "Ordenación temporal de acontecimientos", "Causalidad" to "Relación por la que un proceso contribuye a otro"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Ordenación temporal de acontecimientos.", listOf("Cronología", "Causalidad"), 0, "Cronología: Ordenación temporal de acontecimientos."), ShortQuestion("¿Qué concepto corresponde a esta definición? Relación por la que un proceso contribuye a otro.", listOf("Cronología", "Causalidad"), 1, "Causalidad: Relación por la que un proceso contribuye a otro.")), null, "es-MX", null),
        ShortLesson("HISTORIA:1:0", MateriaId.HISTORIA, 1, "Causas y consecuencias", "Los procesos históricos suelen tener varias causas. Conviene distinguir las condiciones previas de sus consecuencias y considerar diferentes escalas.", "Para estudiar una migración se examinan empleo, conflictos y redes familiares, además de los cambios en los lugares de origen y destino.", "Los procesos históricos suelen tener varias causas.", listOf("Causa" to "Condición que contribuye a un proceso", "Consecuencia" to "Efecto de un proceso"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Condición que contribuye a un proceso.", listOf("Causa", "Consecuencia"), 0, "Causa: Condición que contribuye a un proceso."), ShortQuestion("¿Qué concepto corresponde a esta definición? Efecto de un proceso.", listOf("Causa", "Consecuencia"), 1, "Consecuencia: Efecto de un proceso.")), null, "es-MX", null),
        ShortLesson("HISTORIA:1:1", MateriaId.HISTORIA, 1, "Perspectivas", "Una fuente refleja una posición y un contexto. Comparar testimonios permite identificar coincidencias, desacuerdos y silencios.", "Un diario personal y un informe oficial pueden describir de forma distinta el mismo acontecimiento.", "Una fuente refleja una posición y un contexto.", listOf("Contexto" to "Circunstancias en que se produce una fuente", "Contraste" to "Comparación crítica entre fuentes"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Circunstancias en que se produce una fuente.", listOf("Contexto", "Contraste"), 0, "Contexto: Circunstancias en que se produce una fuente."), ShortQuestion("¿Qué concepto corresponde a esta definición? Comparación crítica entre fuentes.", listOf("Contexto", "Contraste"), 1, "Contraste: Comparación crítica entre fuentes.")), null, "es-MX", null),
        ShortLesson("GEOLOGIA:0:0", MateriaId.GEOLOGIA, 0, "Minerales y rocas", "Un mineral es un sólido natural con estructura interna ordenada y composición característica. Una roca es un agregado de minerales o material geológico.", "El cuarzo es un mineral. El granito es una roca que contiene varios minerales.", "Un mineral es un sólido natural con estructura interna ordenada y composición característica.", listOf("Mineral" to "Sólido natural de estructura ordenada", "Roca" to "Agregado de material geológico"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Sólido natural de estructura ordenada.", listOf("Mineral", "Roca"), 0, "Mineral: Sólido natural de estructura ordenada."), ShortQuestion("¿Qué concepto corresponde a esta definición? Agregado de material geológico.", listOf("Mineral", "Roca"), 1, "Roca: Agregado de material geológico.")), null, "es-MX", null),
        ShortLesson("GEOLOGIA:0:1", MateriaId.GEOLOGIA, 0, "Tipos de rocas", "Las rocas ígneas se forman al solidificarse material fundido. Las sedimentarias se forman por acumulación y consolidación de sedimentos u otros procesos de depósito.", "El basalto es ígneo. Una arenisca se forma a partir de granos de arena consolidados.", "Las rocas ígneas se forman al solidificarse material fundido.", listOf("Ígnea" to "Roca formada al solidificarse material fundido", "Sedimentaria" to "Roca formada por procesos de depósito"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Roca formada al solidificarse material fundido.", listOf("Ígnea", "Sedimentaria"), 0, "Ígnea: Roca formada al solidificarse material fundido."), ShortQuestion("¿Qué concepto corresponde a esta definición? Roca formada por procesos de depósito.", listOf("Ígnea", "Sedimentaria"), 1, "Sedimentaria: Roca formada por procesos de depósito.")), null, "es-MX", null),
        ShortLesson("GEOLOGIA:1:0", MateriaId.GEOLOGIA, 1, "Placas tectónicas", "La litosfera está dividida en placas que se desplazan. En límites divergentes se separan; en convergentes se acercan.", "En una dorsal oceánica las placas se separan y se forma nueva corteza oceánica.", "La litosfera está dividida en placas que se desplazan.", listOf("Divergente" to "Límite donde las placas se separan", "Convergente" to "Límite donde las placas se acercan"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Límite donde las placas se separan.", listOf("Divergente", "Convergente"), 0, "Divergente: Límite donde las placas se separan."), ShortQuestion("¿Qué concepto corresponde a esta definición? Límite donde las placas se acercan.", listOf("Divergente", "Convergente"), 1, "Convergente: Límite donde las placas se acercan.")), null, "es-MX", null),
        ShortLesson("GEOLOGIA:1:1", MateriaId.GEOLOGIA, 1, "Erosión y depósito", "La erosión retira y transporta material. La sedimentación ocurre cuando ese material se deposita.", "Un río transporta arena y puede depositarla cuando disminuye su capacidad de transporte.", "La erosión retira y transporta material.", listOf("Erosión" to "Retirada y transporte de material", "Sedimentación" to "Depósito de material transportado"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Retirada y transporte de material.", listOf("Erosión", "Sedimentación"), 0, "Erosión: Retirada y transporte de material."), ShortQuestion("¿Qué concepto corresponde a esta definición? Depósito de material transportado.", listOf("Erosión", "Sedimentación"), 1, "Sedimentación: Depósito de material transportado.")), null, "es-MX", null),
        ShortLesson("PSICOLOGIA:0:0", MateriaId.PSICOLOGIA, 0, "Conducta y cognición", "La psicología estudia la conducta y los procesos mentales mediante métodos sistemáticos. Distingue lo observable de las inferencias sobre procesos internos.", "Registrar cuánto tarda alguien en responder es una observación; proponer cómo atendió al estímulo es una inferencia.", "La psicología estudia la conducta y los procesos mentales mediante métodos sistemáticos.", listOf("Conducta" to "Actividad observable de un organismo", "Cognición" to "Procesos de adquisición y uso de información"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Actividad observable de un organismo.", listOf("Conducta", "Cognición"), 0, "Conducta: Actividad observable de un organismo."), ShortQuestion("¿Qué concepto corresponde a esta definición? Procesos de adquisición y uso de información.", listOf("Conducta", "Cognición"), 1, "Cognición: Procesos de adquisición y uso de información.")), null, "es-MX", null),
        ShortLesson("PSICOLOGIA:0:1", MateriaId.PSICOLOGIA, 0, "Atención y memoria", "La atención prioriza información para procesarla. La memoria permite conservar y recuperar información; no funciona como una copia exacta de los hechos.", "Atender a una explicación ayuda a codificarla. Intentar recordarla después practica su recuperación.", "La atención prioriza información para procesarla.", listOf("Atención" to "Selección de información para procesarla", "Memoria" to "Conservación y recuperación de información"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Selección de información para procesarla.", listOf("Atención", "Memoria"), 0, "Atención: Selección de información para procesarla."), ShortQuestion("¿Qué concepto corresponde a esta definición? Conservación y recuperación de información.", listOf("Atención", "Memoria"), 1, "Memoria: Conservación y recuperación de información.")), null, "es-MX", null),
        ShortLesson("PSICOLOGIA:1:0", MateriaId.PSICOLOGIA, 1, "Aprendizaje", "El aprendizaje produce cambios relativamente duraderos a partir de la experiencia. Un refuerzo aumenta la probabilidad futura de una conducta en un contexto.", "Si una consecuencia hace que una conducta se repita más, cumple una función de refuerzo, aunque no siempre sea un premio material.", "El aprendizaje produce cambios relativamente duraderos a partir de la experiencia.", listOf("Aprendizaje" to "Cambio relativamente duradero por experiencia", "Refuerzo" to "Consecuencia que aumenta una conducta"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Cambio relativamente duradero por experiencia.", listOf("Aprendizaje", "Refuerzo"), 0, "Aprendizaje: Cambio relativamente duradero por experiencia."), ShortQuestion("¿Qué concepto corresponde a esta definición? Consecuencia que aumenta una conducta.", listOf("Aprendizaje", "Refuerzo"), 1, "Refuerzo: Consecuencia que aumenta una conducta.")), null, "es-MX", null),
        ShortLesson("PSICOLOGIA:1:1", MateriaId.PSICOLOGIA, 1, "Investigación", "Una correlación describe una relación estadística. Un experimento manipula una variable y controla otras para investigar efectos.", "Que horas de sueño y resultados de una tarea estén relacionadas no basta para establecer la causa.", "Una correlación describe una relación estadística.", listOf("Correlación" to "Relación estadística entre variables", "Experimento" to "Estudio con manipulación y control de variables"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Relación estadística entre variables.", listOf("Correlación", "Experimento"), 0, "Correlación: Relación estadística entre variables."), ShortQuestion("¿Qué concepto corresponde a esta definición? Estudio con manipulación y control de variables.", listOf("Correlación", "Experimento"), 1, "Experimento: Estudio con manipulación y control de variables.")), null, "es-MX", null),
        ShortLesson("SOCIOLOGIA:0:0", MateriaId.SOCIOLOGIA, 0, "Sociedad y cultura", "La sociología estudia relaciones, grupos e instituciones. La cultura incluye prácticas, significados, valores y normas compartidos.", "Los saludos varían entre grupos y se aprenden en la interacción social.", "La sociología estudia relaciones, grupos e instituciones.", listOf("Cultura" to "Prácticas y significados compartidos", "Sociedad" to "Conjunto organizado de relaciones sociales"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Prácticas y significados compartidos.", listOf("Cultura", "Sociedad"), 0, "Cultura: Prácticas y significados compartidos."), ShortQuestion("¿Qué concepto corresponde a esta definición? Conjunto organizado de relaciones sociales.", listOf("Cultura", "Sociedad"), 1, "Sociedad: Conjunto organizado de relaciones sociales.")), null, "es-MX", null),
        ShortLesson("SOCIOLOGIA:0:1", MateriaId.SOCIOLOGIA, 0, "Normas y roles", "Las normas son expectativas de conducta. Los roles agrupan expectativas asociadas a una posición social.", "En una clase se espera que el docente oriente la actividad y que el alumnado participe: son expectativas de rol.", "Las normas son expectativas de conducta.", listOf("Norma" to "Expectativa de conducta compartida", "Rol" to "Expectativas vinculadas a una posición"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Expectativa de conducta compartida.", listOf("Norma", "Rol"), 0, "Norma: Expectativa de conducta compartida."), ShortQuestion("¿Qué concepto corresponde a esta definición? Expectativas vinculadas a una posición.", listOf("Norma", "Rol"), 1, "Rol: Expectativas vinculadas a una posición.")), null, "es-MX", null),
        ShortLesson("SOCIOLOGIA:1:0", MateriaId.SOCIOLOGIA, 1, "Instituciones", "Las instituciones son patrones relativamente estables que organizan la vida social. La socialización permite aprender formas de participar en ella.", "La familia y la escuela intervienen en la socialización y pueden transmitir normas diferentes.", "Las instituciones son patrones relativamente estables que organizan la vida social.", listOf("Institución" to "Patrón estable que organiza relaciones sociales", "Socialización" to "Aprendizaje de prácticas y normas sociales"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Patrón estable que organiza relaciones sociales.", listOf("Institución", "Socialización"), 0, "Institución: Patrón estable que organiza relaciones sociales."), ShortQuestion("¿Qué concepto corresponde a esta definición? Aprendizaje de prácticas y normas sociales.", listOf("Institución", "Socialización"), 1, "Socialización: Aprendizaje de prácticas y normas sociales.")), null, "es-MX", null),
        ShortLesson("SOCIOLOGIA:1:1", MateriaId.SOCIOLOGIA, 1, "Desigualdad", "La desigualdad social implica una distribución diferente de recursos y oportunidades. Analizarla requiere observar estructuras además de decisiones individuales.", "Dos personas pueden estudiar con esfuerzos similares y disponer de distinto acceso a transporte o conexión a internet.", "La desigualdad social implica una distribución diferente de recursos y oportunidades.", listOf("Recurso" to "Medio disponible para actuar", "Oportunidad" to "Posibilidad efectiva de acceder a una actividad"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Medio disponible para actuar.", listOf("Recurso", "Oportunidad"), 0, "Recurso: Medio disponible para actuar."), ShortQuestion("¿Qué concepto corresponde a esta definición? Posibilidad efectiva de acceder a una actividad.", listOf("Recurso", "Oportunidad"), 1, "Oportunidad: Posibilidad efectiva de acceder a una actividad.")), null, "es-MX", null),
        ShortLesson("TECNOLOGIA:0:0", MateriaId.TECNOLOGIA, 0, "Hardware y software", "El hardware son los componentes físicos de un sistema informático. El software son programas e instrucciones que ese sistema ejecuta.", "El teclado es hardware. El programa que procesa lo que escribes es software.", "El hardware son los componentes físicos de un sistema informático.", listOf("Hardware" to "Componentes físicos de un sistema", "Software" to "Programas e instrucciones"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Componentes físicos de un sistema.", listOf("Hardware", "Software"), 0, "Hardware: Componentes físicos de un sistema."), ShortQuestion("¿Qué concepto corresponde a esta definición? Programas e instrucciones.", listOf("Hardware", "Software"), 1, "Software: Programas e instrucciones.")), null, "es-MX", null),
        ShortLesson("TECNOLOGIA:0:1", MateriaId.TECNOLOGIA, 0, "Algoritmos", "Un algoritmo es una secuencia definida de pasos para resolver una tarea. Debe especificar entradas, operaciones y resultados.", "Para calcular un promedio: sumar las notas y dividir entre la cantidad de notas.", "Un algoritmo es una secuencia definida de pasos para resolver una tarea.", listOf("Entrada" to "Datos que recibe un algoritmo", "Salida" to "Resultado que produce un algoritmo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Datos que recibe un algoritmo.", listOf("Entrada", "Salida"), 0, "Entrada: Datos que recibe un algoritmo."), ShortQuestion("¿Qué concepto corresponde a esta definición? Resultado que produce un algoritmo.", listOf("Entrada", "Salida"), 1, "Salida: Resultado que produce un algoritmo.")), null, "es-MX", null),
        ShortLesson("TECNOLOGIA:1:0", MateriaId.TECNOLOGIA, 1, "Datos y variables", "Una variable permite identificar un valor que un programa utiliza. El tipo de dato establece qué valores y operaciones admite.", "Una variable edad puede contener un entero; nombre puede contener texto.", "Una variable permite identificar un valor que un programa utiliza.", listOf("Entero" to "Tipo para números sin parte fraccionaria", "Cadena" to "Tipo para secuencias de caracteres"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Tipo para números sin parte fraccionaria.", listOf("Entero", "Cadena"), 0, "Entero: Tipo para números sin parte fraccionaria."), ShortQuestion("¿Qué concepto corresponde a esta definición? Tipo para secuencias de caracteres.", listOf("Entero", "Cadena"), 1, "Cadena: Tipo para secuencias de caracteres.")), null, "es-MX", null),
        ShortLesson("TECNOLOGIA:1:1", MateriaId.TECNOLOGIA, 1, "Redes", "Una red conecta dispositivos para intercambiar datos. Un cliente solicita un servicio y un servidor atiende solicitudes.", "Al abrir una página, el navegador solicita recursos a un servidor web.", "Una red conecta dispositivos para intercambiar datos.", listOf("Cliente" to "Componente que solicita un servicio", "Servidor" to "Componente que atiende solicitudes"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Componente que solicita un servicio.", listOf("Cliente", "Servidor"), 0, "Cliente: Componente que solicita un servicio."), ShortQuestion("¿Qué concepto corresponde a esta definición? Componente que atiende solicitudes.", listOf("Cliente", "Servidor"), 1, "Servidor: Componente que atiende solicitudes.")), null, "es-MX", null),
        ShortLesson("ESCRITURA:0:0", MateriaId.ESCRITURA, 0, "Propósito y destinatario", "Antes de escribir conviene definir qué se quiere lograr y para quién se escribe. Eso orienta el contenido y el registro.", "Un aviso de cambio de horario necesita fecha y acción concreta; un ensayo desarrolla una postura.", "Antes de escribir conviene definir qué se quiere lograr y para quién se escribe.", listOf("Propósito" to "Resultado que busca un texto", "Destinatario" to "Persona o grupo al que se dirige"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Resultado que busca un texto.", listOf("Propósito", "Destinatario"), 0, "Propósito: Resultado que busca un texto."), ShortQuestion("¿Qué concepto corresponde a esta definición? Persona o grupo al que se dirige.", listOf("Propósito", "Destinatario"), 1, "Destinatario: Persona o grupo al que se dirige.")), null, "es-MX", null),
        ShortLesson("ESCRITURA:0:1", MateriaId.ESCRITURA, 0, "El párrafo", "Un párrafo desarrolla una idea principal con detalles pertinentes. La relación entre sus oraciones debe poder seguirse.", "Para explicar un resultado, presenta primero el hallazgo y después los datos que lo sostienen.", "Un párrafo desarrolla una idea principal con detalles pertinentes.", listOf("Idea principal" to "Contenido central de un párrafo", "Detalle" to "Información que desarrolla la idea"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Contenido central de un párrafo.", listOf("Idea principal", "Detalle"), 0, "Idea principal: Contenido central de un párrafo."), ShortQuestion("¿Qué concepto corresponde a esta definición? Información que desarrolla la idea.", listOf("Idea principal", "Detalle"), 1, "Detalle: Información que desarrolla la idea.")), null, "es-MX", null),
        ShortLesson("ESCRITURA:1:0", MateriaId.ESCRITURA, 1, "Argumentación", "Un argumento relaciona una afirmación con razones y evidencia. Una opinión sin apoyo no constituye por sí sola una demostración.", "«La biblioteca debe ampliar su horario» es una propuesta; los registros de demanda pueden aportar evidencia.", "Un argumento relaciona una afirmación con razones y evidencia.", listOf("Tesis" to "Postura que se defiende", "Evidencia" to "Información que respalda una afirmación"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Postura que se defiende.", listOf("Tesis", "Evidencia"), 0, "Tesis: Postura que se defiende."), ShortQuestion("¿Qué concepto corresponde a esta definición? Información que respalda una afirmación.", listOf("Tesis", "Evidencia"), 1, "Evidencia: Información que respalda una afirmación.")), null, "es-MX", null),
        ShortLesson("ESCRITURA:1:1", MateriaId.ESCRITURA, 1, "Revisión", "Revisar implica comprobar estructura, claridad y precisión. Corregir ortografía es una parte de ese proceso.", "Si un texto repite una idea, puede fusionar párrafos antes de revisar tildes y signos.", "Revisar implica comprobar estructura, claridad y precisión.", listOf("Revisión" to "Evaluación del contenido y la organización", "Corrección" to "Enmienda de errores formales"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Evaluación del contenido y la organización.", listOf("Revisión", "Corrección"), 0, "Revisión: Evaluación del contenido y la organización."), ShortQuestion("¿Qué concepto corresponde a esta definición? Enmienda de errores formales.", listOf("Revisión", "Corrección"), 1, "Corrección: Enmienda de errores formales.")), null, "es-MX", null),
        ShortLesson("ANATOMIA:0:0", MateriaId.ANATOMIA, 0, "Posición anatómica", "La posición anatómica sirve como referencia: cuerpo erguido, mirada al frente, brazos a los lados y palmas hacia delante.", "En esta referencia, anterior indica hacia el frente del cuerpo y posterior hacia la espalda.", "La posición anatómica sirve como referencia: cuerpo erguido, mirada al frente, brazos a los lados y palmas hacia delante.", listOf("Anterior" to "Hacia la parte frontal del cuerpo", "Posterior" to "Hacia la parte trasera del cuerpo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Hacia la parte frontal del cuerpo.", listOf("Anterior", "Posterior"), 0, "Anterior: Hacia la parte frontal del cuerpo."), ShortQuestion("¿Qué concepto corresponde a esta definición? Hacia la parte trasera del cuerpo.", listOf("Anterior", "Posterior"), 1, "Posterior: Hacia la parte trasera del cuerpo.")), null, "es-MX", null),
